sub readfa{my $f=shift;my(%s,@o);open my $h,"<",$f or die $!;my $n;while(<$h>){chomp;if(/^>(.*)/){$n=$1;push @o,$n;$s{$n}="";}else{$s{$n}.=$_;}}return (\%s,\@o);}
