# Longest suffix annealing (exact match to circular template / reverse complement)
sub lsp { my ($p,$t,$c)=@_; my ($best,$pos)=(0,-1); for my $L (1..length($p)){my $sub=substr($p,length($p)-$L,$L);my $i=index($c,$sub);if($i>=0&&$i<$N){$best=$L;$pos=$i;}} return($best,$pos); }
